package com.example.books; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.test.context.ActiveProfiles; import static org.assertj.core.api.Assertions.assertThat; @DataJpaTest @ActiveProfiles("h2") class BookRepositoryTest { @Autowired BookRepository repo; @Test void savesAndRetrievesBook(){Book saved=repo.save(new Book("Clean Code","Robert C. Martin")); assertThat(saved.getId()).isNotNull(); var found=repo.findById(saved.getId()); assertThat(found).isPresent(); assertThat(found.get().getTitle()).isEqualTo("Clean Code"); assertThat(found.get().getAuthor()).isEqualTo("Robert C. Martin");} }